const Entry* getFiles() noexcept { return kFiles; }

const Entry* find (const char* fileName) noexcept
{
    if (fileName == nullptr) return nullptr;
    for (int i = 0; i < numFiles; ++i)
        if (std::strcmp (kFiles[i].fileName, fileName) == 0)
            return &kFiles[i];
    return nullptr;
}

bool hasFile (const char* fileName) noexcept
{
    return find (fileName) != nullptr;
}
